import{_ as e,c as o,o as a,a2 as t}from"./chunks/framework.BQGPkCej.js";const b=JSON.parse('{"title":"网页控制台","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick_start/web_console.md","filePath":"guide/quick_start/web_console.md","lastUpdated":1720634491000}'),c={name:"guide/quick_start/web_console.md"},s=t('<h1 id="网页控制台" tabindex="-1">网页控制台 <a class="header-anchor" href="#网页控制台" aria-label="Permalink to &quot;网页控制台&quot;">​</a></h1><h2 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h2><p>要开发网页控制台，需要先进行几项项准备工作：</p><ol><li>前往 <code>config/web-console.yml</code> 配置文件，将 <code>enable</code> 设置为 <code>ture</code>，开启网页控制台</li><li>进入 <code>src/web-console/frontend</code> 目录，执行 <code>pnpm install</code>，安装相关依赖</li><li>在项目根目录执行命令 <code>pnpm dev</code>，以开发模式启动项目</li></ol><h2 id="打包上传" tabindex="-1">打包上传 <a class="header-anchor" href="#打包上传" aria-label="Permalink to &quot;打包上传&quot;">​</a></h2><blockquote><p>在执行此操作前，需要先向开发者申请 <code>upload_token</code>，并填入自动生成的 <code>src/web-console/frontend/build_setting.yml</code> 中</p></blockquote><p>前端开发完毕后，在 <code>src/web-console/frontend</code> 目录下，执行如下命令</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>这个命令将会对前端页面进行打包，并在打包完毕后上传至云服务器。用户启动 bot 时将会检测并自动拉取云端当前 <code>package.json</code> 的版本的新更新文件。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li>若仅对前端页面部分进行了修改，直接打包上传即可。</li><li>若在修改了前端页面的同时，对后端内容也进行了修改，则务必修改根目录下的 <code>package.json</code> 的 <code>version</code> 版本号，然后再打包上传。</li></ol>',11),i=[s];function d(l,n,r,p,h,_){return a(),o("div",null,i)}const k=e(c,[["render",d]]);export{b as __pageData,k as default};
